#!/bin/sh
set -eu

if [ "$#" -ne 1 ]; then
    printf 'Usage: %s DESTINATION\n' "$0" >&2
    exit 2
fi

base=$(CDPATH= cd "$(dirname "$0")/.." && pwd)
dest=$1

# Keep option-like relative destinations from being parsed as command options.
case $dest in
    -*) dest=./$dest ;;
esac

mkdir -p "$dest" || {
    printf '%s: cannot create destination: %s\n' "$0" "$1" >&2
    exit 1
}

for file in summary.txt detail.txt; do
    cp "$base/templates/$file" "$dest/$file" || {
        printf '%s: cannot install %s in destination: %s\n' "$0" "$file" "$1" >&2
        exit 1
    }
done

cp "$base/launcher" "$dest/run-report" || {
    printf '%s: cannot install launcher in destination: %s\n' "$0" "$1" >&2
    exit 1
}
chmod +x "$dest/run-report" || {
    printf '%s: cannot make launcher executable: %s/run-report\n' "$0" "$1" >&2
    exit 1
}
